using System;using System.IO;using System.Linq;using UnityEngine;
namespace LostRealmsOW{public static class HorseProgressionValidation{
 static Vector3 visualPosition;static bool visualBlocked;
 public static void StableView(){var gm=UnityEngine.Object.FindObjectsByType<OpenWorldManager>().First(g=>g.Hero);visualPosition=gm.Hero.transform.position;var f=typeof(OpenWorldManager).GetField("saveBlocked",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic);visualBlocked=(bool)f.GetValue(gm);f.SetValue(gm,true);gm.Hero.WarpTo(OpenWorldHorseProgression.Stable+Vector3.right*5);gm.CameraRig.enabled=false;Camera.main.transform.position=gm.Hero.transform.position+new Vector3(5,4,-8);Camera.main.transform.LookAt(OpenWorldHorseProgression.Stable+Vector3.up*7);}
 public static void TamingView(){var gm=UnityEngine.Object.FindObjectsByType<OpenWorldManager>().First(g=>g.Hero);var horse=UnityEngine.Object.FindObjectsByType<OpenWorldAnimalInteraction>().First(a=>a.Horse&&!a.Owned);gm.Hero.WarpTo(horse.transform.position+Vector3.back*2);OpenWorldHorseProgression.Begin(horse);Camera.main.transform.position=horse.transform.position+new Vector3(5,3,-5);Camera.main.transform.LookAt(horse.transform.position+Vector3.up);}
 public static void EndView(){if(OpenWorldHorseProgression.Instance)OpenWorldHorseProgression.Instance.Cancel();var gm=UnityEngine.Object.FindObjectsByType<OpenWorldManager>().First(g=>g.Hero);gm.Hero.WarpTo(visualPosition);typeof(OpenWorldManager).GetField("saveBlocked",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).SetValue(gm,visualBlocked);}
 public static void Run(){var gm=UnityEngine.Object.FindObjectsByType<OpenWorldManager>().First(g=>g.Hero);var flags=gm.CollectedWorldIds.ToArray();int gold=gm.Gold,weapon=gm.Hero.EquippedWeaponId;Vector3 pos=gm.Hero.transform.position;var field=typeof(OpenWorldManager).GetField("saveBlocked",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic);bool blocked=(bool)field.GetValue(gm);var lines=new System.Collections.Generic.List<string>();void Check(bool ok,string label){lines.Add((ok?"PASS ":"FAIL ")+label);}
 try{field.SetValue(gm,true);gm.CloseMenus();gm.CollectedWorldIds.RemoveWhere(f=>f.StartsWith("horse-"));Check(!OpenWorldWeaponCatalog.Available(17),"retired axe unavailable");gm.Hero.EquipWeapon(17);Check(gm.Hero.EquippedWeaponId==-1,"old equipped axe becomes unarmed");var wild=UnityEngine.Object.FindObjectsByType<OpenWorldAnimalInteraction>().FirstOrDefault(a=>a.Horse&&!a.Owned);if(wild)Check(!wild.Mount(gm.Hero),"wild horse cannot mount without taming");gm.Hero.WarpTo(OpenWorldHorseProgression.Stable+Vector3.right*5);gm.Gold=0;Check(!OpenWorldHorseProgression.Instance.Buy(0)&&gm.Gold==0,"stable rejects insufficient funds");gm.Gold=1000;Check(OpenWorldHorseProgression.Instance.Buy(0)&&gm.Gold==650,"stable charges exactly350");Check(gm.CollectedWorldIds.Contains("horse-owned:0"),"ownership recorded");Check(OpenWorldHorseProgression.Instance.Buy(0)&&gm.Gold==650,"owned horse reselection free");var trialObject=new GameObject("isolated wild horse trial");trialObject.transform.position=gm.Hero.transform.position;var trial=trialObject.AddComponent<OpenWorldAnimalInteraction>();trial.Horse=true;trial.Breed=1;var progress=OpenWorldHorseProgression.Instance;OpenWorldHorseProgression.Begin(trial);Check(progress.Target==trial,"taming challenge starts");progress.Counter(0);progress.Counter(0);progress.Counter(0);Check(!progress.Target&&!gm.CollectedWorldIds.Contains("horse-owned:1"),"three taming errors fail without ownership");typeof(OpenWorldHorseProgression).GetField("retryAt",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance).SetValue(progress,0f);OpenWorldHorseProgression.Begin(trial);int required=progress.Required;for(int i=0;i<required;i++)progress.Counter(progress.Direction);Check(gm.CollectedWorldIds.Contains("horse-owned:1")&&gm.CollectedWorldIds.Contains("horse-skill:1"),"successful challenge grants horse and handling skill");UnityEngine.Object.Destroy(trialObject);Check(OpenWorldHorseProgression.Breeds[1].Speed>OpenWorldHorseProgression.Breeds[0].Speed&&OpenWorldHorseProgression.Breeds[2].Stamina>OpenWorldHorseProgression.Breeds[1].Stamina,"breed speed stamina differ");var data=gm.CaptureAdventure();string dir=Path.Combine(Application.temporaryCachePath,"HorseProgress-"+Guid.NewGuid().ToString("N"));var store=new OpenWorldSaveStore(dir);data.collected=data.collected.Concat(new[]{"ore-ready:2:"+(DateTimeOffset.UtcNow.ToUnixTimeSeconds()+86400)}).ToArray();store.Write(data);var loaded=store.Load();Check(loaded.collected.Contains("horse-owned:0")&&loaded.collected.Any(f=>f.StartsWith("ore-ready:2:")),"ownership and ore deadline survive save round trip");}
 finally{gm.CollectedWorldIds.Clear();gm.CollectedWorldIds.UnionWith(flags);gm.Gold=gold;gm.Hero.EquipWeapon(weapon);gm.Hero.WarpTo(pos);field.SetValue(gm,blocked);foreach(var a in UnityEngine.Object.FindObjectsByType<OpenWorldAnimalInteraction>().Where(a=>a.Owned))UnityEngine.Object.Destroy(a.gameObject);File.WriteAllLines("Docs/QA/HORSE_PROGRESSION.txt",lines);Debug.Log(string.Join("\n",lines));}
 }
